SELECT 'gongkao', '指代词理解', 'kp-xingce-language-reading-word-sentence-reference', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "指代词理解"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心战术：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "“这”、“它”、“此”。绝对在它前面找！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[圈出题干要求解释的指代词(如'这种情况')] --> B[目光紧贴着该词, 向【前】倒退半句或一句]\nB --> C[提取前文的主语或核心动作]\nC --> D[带入替换指代词, 读一遍是否通顺]"}}]}$$ AS jsonb), NULL, '指代词理解的核心考点与解题技巧。', category_node.id, CAST('["言语理解", "片段阅读", "指代词理解"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_language_reading_word_sentence_reference", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
